1	using System.Diagnostics;
2	using System.Text.Json;
3	using MonoDreams.Input;
4	using MonoDreams.State;
5	
6	namespace MonoDreams.Tests;
7	
8	public class GameTestResult
9	{
10	    public int ExitCode { get; init; }
11	    public List<string> LogLines { get; init; } = new();
12	
13	    public void AssertLogContains(string substring)
14	    {
15	        Assert.Contains(LogLines, line => line.Contains(substring, StringComparison.OrdinalIgnoreCase));
16	    }
17	
18	    public void AssertLogContainsInOrder(params string[] substrings)
19	    {
20	        int searchFrom = 0;
21	        foreach (var substring in substrings)
22	        {
23	            int found = -1;
24	            for (int i = searchFrom; i < LogLines.Count; i++)
25	            {
26	                if (LogLines[i].Contains(substring, StringComparison.OrdinalIgnoreCase))
27	                {
28	                    found = i;
29	                    break;
30	                }
31	            }
32	
33	            Assert.True(found >= 0, $"Expected log to contain '{substring}' after line {searchFrom}, but it was not found.");
34	            searchFrom = found + 1;
35	        }
36	    }
37	
38	    public List<string> GetLogLines(LogLevel level)
39	    {
40	        var tag = level switch
41	        {
42	            LogLevel.Debug => "[DEBUG]",
43	            LogLevel.Info => "[ INFO]",
44	            LogLevel.Warning => "[ WARN]",
45	            LogLevel.Error => "[ERROR]",
46	            _ => throw new ArgumentOutOfRangeException(nameof(level))
47	        };
48	        return LogLines.Where(l => l.Contains(tag)).ToList();
49	    }
50	}
51	
52	public static class GameTestRunner
53	{
54	    /// <summary>
55	    /// Finds the repo root by walking up from the test assembly's base directory
56	    /// looking for the MonoDreams.Examples directory.
57	    /// </summary>
58	    private static string FindRepoRoot()
59	    {
60	        var dir = AppDomain.CurrentDomain.BaseDirectory;
61	        while (dir != null)
62	        {
63	            if (Directory.Exists(Path.Combine(dir, "MonoDreams.Examples")))
64	                return dir;
65	            dir = Directory.GetParent(dir)?.FullName;
66	        }
67	        throw new InvalidOperationException("Could not find repo root (directory containing MonoDreams.Examples).");
68	    }
69	
70	    public static async Task<GameTestResult> RunAsync(InputReplayPlan plan, int timeoutSeconds = 30)
71	    {
72	        var repoRoot = FindRepoRoot();
73	        var debugDir = Path.Combine(Path.GetTempPath(), "monodreams_test_" + Guid.NewGuid().ToString("N")[..8]);
74	        Directory.CreateDirectory(debugDir);
75	
76	        // Write the replay plan
77	        var replayJson = JsonSerializer.Serialize(plan, new JsonSerializerOptions { WriteIndented = true });
78	        await File.WriteAllTextAsync(Path.Combine(debugDir, "input_replay.json"), replayJson);
79	
80	        // Spawn the game process
81	        var psi = new ProcessStartInfo
82	        {
83	            FileName = "dotnet",
84	            Arguments = "run --project MonoDreams.Examples -- --headless",
85	            WorkingDirectory = repoRoot,
86	            RedirectStandardOutput = true,
87	            RedirectStandardError = true,
88	            UseShellExecute = false,
89	            CreateNoWindow = true,
90	        };
91	        psi.Environment["MONODREAMS_DEBUG_DIR"] = debugDir;
92	
93	        using var process = Process.Start(psi)!;
94	        using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(timeoutSeconds));
95	
96	        try
97	        {
98	            await process.WaitForExitAsync(cts.Token);
99	        }
100	        catch (OperationCanceledException)
101	        {
102	            process.Kill(entireProcessTree: true);
103	            throw new TimeoutException($"Game process did not exit within {timeoutSeconds}s.");
104	        }
105	
