1	using System.Collections.Generic;
2	using System.Linq;
3	using DefaultEcs;
4	using DefaultEcs.System;
5	using Microsoft.Xna.Framework;
6	using Microsoft.Xna.Framework.Graphics;
7	using MonoDreams.Component;
8	using MonoDreams.Component.Draw;
9	using MonoDreams.State;
10	using MonoGame.Extended.BitmapFonts;
11	
12	namespace MonoDreams.System.Draw;
13	
14	/// <summary>
15	/// Unified rendering system that handles all draw types: sprites, text, nine-patch, and mesh.
16	/// This system is game-agnostic - it only renders what's in DrawComponent without any
17	/// specialized component handling.
18	/// </summary>
19	public class MasterRenderSystem(
20	    SpriteBatch spriteBatch,
21	    GraphicsDevice graphicsDevice,
22	    MonoDreams.Component.Camera camera,
23	    IReadOnlyDictionary<RenderTargetID, RenderTarget2D> renderTargets,
24	    World world,
25	    SamplerState? spriteSampler = null,
26	    SamplerState? textSampler = null) : ISystem<GameState>
27	{
28	    private BasicEffect? _basicEffect;
29	
30	    // One EntitySet per render target, built lazily and reused for the
31	    // lifetime of the system. AsSet() registers subscriptions on the World
32	    // that the World keeps alive forever — building a fresh set every frame
33	    // (as this used to) leaks an EntitySet + its subscriptions per target per
34	    // frame, so memory climbs even on a static scene. See premise
35	    // "Per-target draw sets are built once, not per frame".
36	    private readonly Dictionary<RenderTargetID, EntitySet> _drawSets = new();
37	
38	    private EntitySet GetDrawSet(RenderTargetID target)
39	    {
40	        if (_drawSets.TryGetValue(target, out var set))
41	            return set;
42	
43	        var queryBuilder = world.GetEntities()
44	            .With((in DrawComponent e) => e.Target == target);
45	
46	        // Main target: respect CullingSystem visibility. HUD/UI: always render.
47	        if (target == RenderTargetID.Main)
48	            queryBuilder = queryBuilder.With<VisibleComponent>();
49	
50	        set = queryBuilder.AsSet();
51	        _drawSets[target] = set;
52	        return set;
53	    }
54	
55	    // Pixel art wants nearest-neighbour for sprites (and meshes); downscaled bitmap fonts
56	    // read better with linear filtering — so each draw type gets its own sampler. Both are
57	    // overridable per game; the defaults suit this engine's pixel-art content.
58	    private SamplerState SpriteSamplerState => spriteSampler ?? SamplerState.PointClamp;
59	    private SamplerState TextSamplerState => textSampler ?? SamplerState.LinearClamp;
60	
61	    private enum BatchType { None, Sprite, Text, Mesh }
62	
63	    private static BatchType GetBatchType(DrawElementType type) => type switch
64	    {
65	        DrawElementType.Mesh => BatchType.Mesh,
66	        DrawElementType.Text => BatchType.Text,
67	        _ => BatchType.Sprite,
68	    };
69	
70	    private void EnsureBasicEffect()
71	    {
72	        _basicEffect ??= new BasicEffect(graphicsDevice)
73	        {
74	            VertexColorEnabled = true,
75	            View = Matrix.Identity,
76	            Projection = Matrix.CreateOrthographicOffCenter(0, camera.VirtualWidth, camera.VirtualHeight, 0, 0, 1)
77	        };
78	    }
79	
80	    private void BeginSpriteBatch(Matrix transformMatrix, SamplerState samplerState)
81	    {
82	        spriteBatch.Begin(
83	            sortMode: SpriteSortMode.Deferred, // We pre-sort, so no need for FrontToBack
84	            blendState: BlendState.AlphaBlend,
85	            samplerState: samplerState,
86	            depthStencilState: DepthStencilState.None,
87	            rasterizerState: RasterizerState.CullNone,
88	            effect: null,
89	            transformMatrix: transformMatrix);
90	    }
91	
92	    private void EndSpriteBatch() => spriteBatch.End();
93	
94	    private void ResetGraphicsStateForMeshRendering()
95	    {
96	        // Reset states after SpriteBatch.End() before mesh rendering
97	        graphicsDevice.BlendState = BlendState.AlphaBlend;
98	        graphicsDevice.DepthStencilState = DepthStencilState.None;
99	        graphicsDevice.RasterizerState = RasterizerState.CullNone;
100	        graphicsDevice.SamplerStates[0] = SamplerState.PointClamp;
101	    }
102	
103	    public void Update(GameState state)
104	    {
105	        EnsureBasicEffect();
106	
107	        foreach (var renderTarget in renderTargets)
108	        {
109	            var drawList = GetDrawSet(renderTarget.Key);
110	
111	            graphicsDevice.SetRenderTarget(renderTarget.Value);
112	            graphicsDevice.Clear(Color.Transparent);
113	
114	            var transformMatrix = Matrix.Identity;
115	            if (renderTarget.Key == RenderTargetID.Main)
116	            {
117	                transformMatrix = camera.GetViewTransformationMatrix();
118	            }
119	
120	            // Sort ALL entities by LayerDepth (stable sort preserves order for same depth)
121	            var entities = drawList.GetEntities().ToArray();
122	            var sortedEntities = entities
123	                .Select((entity, index) => (entity, index, dc: entity.Get<DrawComponent>()))
124	                .Where(x => x.dc.Type != DrawElementType.Mesh || x.dc.HasValidMesh)
125	                .OrderBy(x => x.dc.LayerDepth)
126	                .ThenBy(x => x.index) // Stable sort
127	                .ToList();
128	
129	            if (sortedEntities.Count > 0)
130	            {
131	                RenderInterleaved(sortedEntities, transformMatrix);
132	            }
133	        }
134	    }
135	
136	    private void RenderInterleaved(
137	        List<(Entity entity, int index, DrawComponent dc)> sortedEntities,
138	        Matrix transformMatrix)
139	    {
140	        BatchType currentBatch = BatchType.None;
141	
142	        foreach (var (_, _, dc) in sortedEntities)
143	        {
144	            var requiredBatch = GetBatchType(dc.Type);
145	
146	            // Batch type changed - switch context. Sprite and Text both use the SpriteBatch
147	            // but with different samplers, so switching between them flushes + reopens it.
148	            // Painter's order is preserved because the list is already depth-sorted.
149	            if (requiredBatch != currentBatch)
150	            {
151	                // End previous batch
152	                if (currentBatch is BatchType.Sprite or BatchType.Text)
153	                    EndSpriteBatch();
154	
155	                // Start new batch
156	                if (requiredBatch == BatchType.Sprite)
157	                    BeginSpriteBatch(transformMatrix, SpriteSamplerState);
158	                else if (requiredBatch == BatchType.Text)
159	                    BeginSpriteBatch(transformMatrix, TextSamplerState);
160	                else if (requiredBatch == BatchType.Mesh)
161	                    ResetGraphicsStateForMeshRendering();
162	
163	                currentBatch = requiredBatch;
164	            }
165	
166	            // Draw the element
167	            if (requiredBatch == BatchType.Mesh)
168	                DrawSingleMesh(dc, transformMatrix);
169	            else
170	                DrawElement(dc); // Sprite or Text
171	        }
172	
173	        // End final batch if it was a SpriteBatch one
174	        if (currentBatch is BatchType.Sprite or BatchType.Text)
175	            EndSpriteBatch();
176	    }
177	
178	    private void DrawSingleMesh(DrawComponent dc, Matrix transformMatrix)
179	    {
180	        if (!dc.HasValidMesh) return;
181	
182	        _basicEffect!.Projection = Matrix.CreateOrthographicOffCenter(
183	            0, camera.VirtualWidth, camera.VirtualHeight, 0, 0, 1);
184	        _basicEffect.World = (dc.WorldMatrix ?? Matrix.Identity) * transformMatrix;
185	
186	        foreach (var pass in _basicEffect.CurrentTechnique.Passes)
187	        {
188	            pass.Apply();
189	            graphicsDevice.DrawUserIndexedPrimitives(
190	                dc.PrimitiveType,
191	                dc.Vertices,
192	                0,
193	                dc.Vertices!.Length,
194	                dc.Indices,
195	                0,
196	                dc.GetPrimitiveCount());
197	        }
198	    }
199	
200	    private void DrawElement(DrawComponent element)
201	    {
202	        switch (element.Type)
203	        {
204	            case DrawElementType.Sprite:
205	                if (element.Texture == null) return;
206	
207	                // Calculate scale from source to destination size for sub-pixel precision
208	                Vector2 scale;
209	                if (element.SourceRectangle.HasValue && element.SourceRectangle.Value.Width > 0 && element.SourceRectangle.Value.Height > 0)
210	                {
211	                    scale = new Vector2(
212	                        element.Size.X / element.SourceRectangle.Value.Width,
213	                        element.Size.Y / element.SourceRectangle.Value.Height);
214	                }
215	                else
216	                {
217	                    scale = element.Scale;
218	                }
219	
220	                spriteBatch.Draw(
221	                    element.Texture,
222	                    element.Position,  // Vector2 preserves sub-pixel precision
223	                    element.SourceRectangle,
224	                    element.Color,
225	                    element.Rotation,
226	                    element.Origin,
227	                    scale,
228	                    SpriteEffects.None,
229	                    element.LayerDepth);
230	                break;
231	
232	            case DrawElementType.Text:
233	                if (element.Font == null || element.Text == null) return;
234	
235	                // Lay out multi-line text ourselves: one DrawString per '\n'-separated line,
236	                // advancing by the (scaled) font line height × LineSpacing. This gives a
237	                // configurable, scale-correct leading instead of relying on the font backend's
238	                // internal newline advance (which ignores the draw scale and overlaps lines).
239	                var lineSpacing = element.LineSpacing > 0 ? element.LineSpacing : DynamicTextComponent.DefaultLineSpacing;
240	                var lineAdvance = element.Font.LineHeight * element.Scale.Y * lineSpacing;
241	                var lines = element.Text.Split('\n');
242	                for (var i = 0; i < lines.Length; i++)
243	                {
244	                    spriteBatch.DrawString(
245	                        element.Font,
246	                        lines[i],
247	                        element.Position + new Vector2(0f, i * lineAdvance),
248	                        element.Color,
249	                        element.Rotation,
250	                        element.Origin,
251	                        element.Scale,
252	                        SpriteEffects.None,
253	                        element.LayerDepth);
254	                }
255	                break;
256	
